"""Note 99 : page de test isolee, principal materiel inchange."""
import argparse,json,pathlib,re,shutil
ROOT=pathlib.Path(__file__).resolve().parents[1]
STAMP='2026-10-16-beat-repeat-test-2'
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--data',required=True);a=p.parse_args();out=ROOT/'docs/flasher-beat-repeat-test';out.mkdir(exist_ok=True)
    for src in (ROOT/'docs/flasher').iterdir():
        if not src.is_file() or src.suffix=='.wav' or src.name in ('ABOUT.md','beat-repeat.js','beat-repeat-data.js'):continue
        raw=src.read_bytes()
        if src.name=='index.html':
            s=raw.decode('utf-8');s=re.sub(r'<script src="beat-repeat(?:-data)?\.js[^"]*"></script>','',s);s=re.sub(r'<p class="alert" id="beat-repeat-status">.*?</p>','',s);s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s)
            s=s.replace("<title>A.V.'s Supermodel Edition.</title>",'<title>Control All Beat Repeat — experimental test</title>')
            banner='<p class="alert"><span data-l="en"><strong>Experimental Control All Beat Repeat.</strong> Hold TRACK + RETRIG, then hold a TRIG key to repeat the Control All included audio tracks. Release either modifier to stop. No dedicated screen or master FX. Hardware testing pending. <a href="../flasher/">Hardware-tested main</a>.</span><span data-l="fr"><strong>Beat Repeat collectif experimental.</strong> Maintenez TRACK + RETRIG puis un TRIG pour repeter les pistes audio incluses dans Control All. Relachez un modificateur pour arreter. Aucun ecran dedie ni FX master. Test materiel attendu. <a href="../flasher/">Principal teste sur machine</a>.</span></p>'
            s=s.replace('<main class="wrap fl">','<main class="wrap fl">'+banner)
            s=s.replace('</body>',f'<script src="beat-repeat-data.js?v={STAMP}"></script><script src="beat-repeat.js?v={STAMP}"></script></body>')
            s=s.replace('href="convert.html"','href="../flasher/convert.html"');raw=s.encode('utf-8')
            raw=raw.replace(b'../assets/release.js?',b'beat-release.js?')
        if src.name=='quick-reference.md':raw=raw.split(b'\n## Control All Beat Repeat')[0];raw+=b'\n## Control All Beat Repeat (experimental)\n\nHold TRACK + RETRIG throughout, then hold a TRIG key. Release either modifier to stop. Control All Config chooses which tracks repeat. Hold both modifiers to replace its track choices with all sixteen repeat divisions; no dedicated screen or master FX. TRIG 3 = 1/32; TRIG 5 = 1/16; TRIG 7 = 1/8; TRIG 10 = 1/4; TRIG 16 = one bar (long slices halve at slow tempos). Newest held TRIG wins. Outgoing MIDI notes are not repeated. Hardware testing pending.\n'
        if src.name=='quick-reference-fr.md':raw=raw.split(b'\n## Beat Repeat collectif')[0];raw+=b'\n## Beat Repeat collectif (experimental)\n\nMaintenez TRACK + RETRIG pendant tout le geste, puis tenez un TRIG. Relachez un modificateur pour arreter. Control All Config choisit les pistes. Les deux modificateurs tenus, seize divisions remplacent les choix de pistes ; aucun ecran dedie ni FX master. TRIG 3 = 1/32 ; TRIG 5 = 1/16 ; TRIG 7 = 1/8 ; TRIG 10 = 1/4 ; TRIG 16 = une mesure (longues boucles reduites aux tempos lents). Le dernier TRIG tenu gagne. Notes MIDI sortantes non repetees. Test materiel attendu.\n'
        if src.suffix in ('.js','.html','.css','.md','.txt'):raw=('\n'.join(line.rstrip() for line in raw.decode('utf-8').splitlines()).rstrip()+'\n').encode('utf-8')
        (out/src.name).write_bytes(raw)
    data=json.loads(pathlib.Path(a.data).read_text());(out/'beat-repeat-data.js').write_text('// Code propre uniquement ; genere par tools/gen_beat_repeat.py.\nwindow.MCBeatRepeat='+json.dumps(data,separators=(',',':'))+';\n',encoding='utf-8')
    shutil.copyfile(ROOT/'tweaks/model-cycles_OS1.13/LICENSE-Model-TG',out/'LICENSE-Beat-Repeat.txt')
    (out/'beat-release.js').write_text('window.MC_RELEASES='+json.dumps([{'version':'1.73-beat-repeat-preview.2','date':'2026-10-16','changes':[{'en':'Test 2: repeat follows Control All Config selection; all sixteen TRIGs select divisions while TRACK + RETRIG hides the config choices. Hold TRACK + RETRIG, then a TRIG key; release either modifier to stop. All six audio tracks, no dedicated page or master FX. Hardware testing pending.','fr':'Test 2 : repetition selon Control All Config ; seize TRIG pour les divisions, choix config masques avec TRACK + RETRIG. Maintenez TRACK + RETRIG puis un TRIG ; relachez un modificateur pour arreter. Six pistes audio, aucun ecran dedie ni FX master. Test materiel attendu.'}]}],ensure_ascii=False)+';\n',encoding='utf-8')
    (out/'TEST-NOTES.md').write_text('''# Control All Beat Repeat / Beat Repeat collectif

EN: Experimental; main is unchanged. Start a test pattern with all six tracks. In Control All Config, exclude some tracks first: only included tracks should repeat, excluded tracks should keep playing normally. The config choices must disappear while TRACK + RETRIG is held and return on release. Hold TRACK + RETRIG, then hold TRIG 3 (1/32), 5 (1/16), 7 (1/8) or 10 (1/4). Release RETRIG first, then try releasing TRACK first: both must return immediately through a short fade to normal playback. No latch. Try both modifier orders, changing rates, stopping transport and another project. Confirm Control All track selection and ordinary trigs stay intact. With Wizard, check a stereo sample. Report clicks, timing, unexpected screens and heavy-load audio glitches. This repeats track audio; it does not repeat outgoing MIDI notes.

FR : Experimental ; principal inchange. Lancez un pattern de test avec six pistes. Excluez des pistes dans Control All Config : seules les incluses doivent repeter. Les choix config disparaissent avec TRACK + RETRIG et reviennent au relachement. Maintenez TRACK + RETRIG puis TRIG 3 (1/32), 5 (1/16), 7 (1/8) ou 10 (1/4). Relachez RETRIG puis essayez TRACK d'abord : retour normal par un court fondu dans les deux cas. Aucun latch. Testez les deux ordres, changements de division, Stop et un autre projet. Verifiez le masque Control All et les TRIG normaux. Avec Wizard, testez un sample stereo. Rapportez clics, timing, ecrans inattendus et glitches en forte charge. Audio repete ; notes MIDI sortantes non repetees.
''',encoding='utf-8')
    print('ok page beat repeat experimentale separee ; principal inchange')
if __name__=='__main__':main()
